package com.jobpilot.api.domain.review.controller;import com.jobpilot.api.domain.review.service.ReviewOperationsService;import com.jobpilot.api.global.security.AuthenticatedMember;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/reviews")public class AdminReviewController{private final ReviewOperationsService s;public AdminReviewController(ReviewOperationsService s){this.s=s;}@GetMapping("/reports")public List<Map<String,Object>>reports(Authentication a){return s.reports(AuthenticatedMember.id(a));}public record Action(String action,String reason){}@PostMapping("/{id}/moderate")public void moderate(@PathVariable long id,@RequestBody Action i,Authentication a){s.moderate(AuthenticatedMember.id(a),id,i.action(),i.reason());}}
